      System.arraycopy(inClose, historyLen - cap_ShadowLongTrailingIdx, capRing_ShadowLongTrailingIdx_inClose, 0, cap_ShadowLongTrailingIdx);
      int cap_ShadowVeryShortTrailingIdx = i - ShadowVeryShortTrailingIdx;
