      double prev_Q1_input_Even;
      double[] jI_Odd;
      double[] jI_Even;
      double jI;
      double prev_jI_Odd;
      double prev_jI_Even;
      double prev_jI_input_Odd;
      double prev_jI_input_Even;
      double[] jQ_Odd;
      double[] jQ_Even;
      double jQ;
      double prev_jQ_Odd;
      double prev_jQ_Even;
      double prev_jQ_input_Odd;
      double prev_jQ_input_Even;
      double Q2;
      double I2;
      double prevQ2;
      double prevI2;
