      iTrend2 = iTrend3;
      iTrend1 = iTrend2;
      daysInTrend = 0;
      DCPhase = 0.0;
      prevDCPhase = DCPhase;
      sine = 0.0;
      prevSine = sine;
      leadSine = 0.0;
      prevLeadSine = leadSine;
      tempReal = Math.atan(1);
      rad2Deg = 45.0 / tempReal;
      deg2Rad = 1.0 / rad2Deg;
