      RetCode retCode = LN_Internal(startIdx, endIdx, inReal, outBegIdx, outNBElement, outReal);
      if( retCode != RetCode.Success ) {
         throw failure("LN", retCode);
      }
      return new OutRange(outBegIdx.value, outNBElement.value);
